package output

import (
	"fmt"
	"io"

	"github.com/yannh/kubeconform/pkg/validator"
)

type Output interface {
	Write(validator.Result) error
	Flush() error
}

func New(w io.Writer, outputFormat string, printSummary, isStdin, verbose bool) (Output, error) {
	switch {
	case outputFormat == "json":
		return jsonOutput(w, printSummary, isStdin, verbose), nil
	case outputFormat == "junit":
		return junitOutput(w, printSummary, isStdin, verbose), nil
	case outputFormat == "pretty":
		return prettyOutput(w, printSummary, isStdin, verbose), nil
	case outputFormat == "tap":
		return tapOutput(w, printSummary, isStdin, verbose), nil
	case outputFormat == "text":
		return textOutput(w, printSummary, isStdin, verbose), nil
	default:
		return nil, fmt.Errorf("'outputFormat' must be 'json', 'junit', 'pretty', 'tap' or 'text'")
	}
}
package output

import (
	"fmt"
	"io"
	"sync"

	"github.com/yannh/kubeconform/pkg/validator"
)

type texto struct {
	sync.Mutex
	w                                   io.Writer
	withSummary                         bool
	isStdin                             bool
	verbose                             bool
	files                               map[string]bool
	nValid, nInvalid, nErrors, nSkipped int
}

// Text will output the results of the validation as a texto
func textOutput(w io.Writer, withSummary, isStdin, verbose bool) Output {
	return &texto{
		w:           w,
		withSummary: withSummary,
		isStdin:     isStdin,
		verbose:     verbose,
		files:       map[string]bool{},
		nValid:      0,
		nInvalid:    0,
		nErrors:     0,
		nSkipped:    0,
	}
}

func (o *texto) Write(result validator.Result) error {
	o.Lock()
	defer o.Unlock()

	var err error

	sig, _ := result.Resource.Signature()

	o.files[result.Resource.Path] = true
	switch result.Status {
	case validator.Valid:
		if o.verbose {
			_, err = fmt.Fprintf(o.w, "%s - %s %s is valid\n", result.Resource.Path, sig.Kind, sig.Name)
		}
		o.nValid++
	case validator.Invalid:
		_, err = fmt.Fprintf(o.w, "%s - %s %s is invalid: %s\n", result.Resource.Path, sig.Kind, sig.Name, result.Err)
		o.nInvalid++
	case validator.Error:
		if sig.Kind != "" && sig.Name != "" {
			_, err = fmt.Fprintf(o.w, "%s - %s %s failed validation: %s\n", result.Resource.Path, sig.Kind, sig.Name, result.Err)
		} else {
			_, err = fmt.Fprintf(o.w, "%s - failed validation: %s\n", result.Resource.Path, result.Err)
		}
		o.nErrors++
	case validator.Skipped:
		if o.verbose {
			_, err = fmt.Fprintf(o.w, "%s - %s %s skipped\n", result.Resource.Path, sig.Name, sig.Kind)
		}
		o.nSkipped++
	case validator.Empty: // sent to ensure we count the filename as parsed
	}

	return err
}

func (o *texto) Flush() error {
	var err error
	if o.withSummary {
		nFiles := len(o.files)
		nResources := o.nValid + o.nInvalid + o.nErrors + o.nSkipped
		resourcesPlural := ""
		if nResources > 1 {
			resourcesPlural = "s"
		}
		filesPlural := ""
		if nFiles > 1 {
			filesPlural = "s"
		}
		if o.isStdin {
			_, err = fmt.Fprintf(o.w, "Summary: %d resource%s found parsing stdin - Valid: %d, Invalid: %d, Errors: %d, Skipped: %d\n", nResources, resourcesPlural, o.nValid, o.nInvalid, o.nErrors, o.nSkipped)
		} else {
			_, err = fmt.Fprintf(o.w, "Summary: %d resource%s found in %d file%s - Valid: %d, Invalid: %d, Errors: %d, Skipped: %d\n", nResources, resourcesPlural, nFiles, filesPlural, o.nValid, o.nInvalid, o.nErrors, o.nSkipped)
		}
	}

	return err
}
package output

import (
	"fmt"
	"io"
	"sync"

	"github.com/yannh/kubeconform/pkg/validator"
)

type prettyo struct {
	sync.Mutex
	w                                   io.Writer
	withSummary                         bool
	isStdin                             bool
	verbose                             bool
	files                               map[string]bool
	nValid, nInvalid, nErrors, nSkipped int
}

// Text will output the results of the validation as a texto
func prettyOutput(w io.Writer, withSummary, isStdin, verbose bool) Output {
	return &prettyo{
		w:           w,
		withSummary: withSummary,
		isStdin:     isStdin,
		verbose:     verbose,
		files:       map[string]bool{},
		nValid:      0,
		nInvalid:    0,
		nErrors:     0,
		nSkipped:    0,
	}
}

func (o *prettyo) Write(result validator.Result) error {
	checkmark := "\u2714"
	multiplicationSign := "\u2716"
	reset := "\033[0m"
	cRed := "\033[31m"
	cGreen := "\033[32m"
	cYellow := "\033[33m"

	o.Lock()
	defer o.Unlock()

	var err error

	sig, _ := result.Resource.Signature()

	o.files[result.Resource.Path] = true
	switch result.Status {
	case validator.Valid:
		if o.verbose {
			fmt.Fprintf(o.w, "%s%s%s %s: %s%s %s is valid%s\n", cGreen, checkmark, reset, result.Resource.Path, cGreen, sig.Kind, sig.Name, reset)
		}
		o.nValid++
	case validator.Invalid:
		fmt.Fprintf(o.w, "%s%s%s %s: %s%s %s is invalid: %s%s\n", cRed, multiplicationSign, reset, result.Resource.Path, cRed, sig.Kind, sig.Name, result.Err.Error(), reset)

		o.nInvalid++
	case validator.Error:
		fmt.Fprintf(o.w, "%s%s%s %s: ", cRed, multiplicationSign, reset, result.Resource.Path)
		if sig.Kind != "" && sig.Name != "" {
			fmt.Fprintf(o.w, "%s%s failed validation: %s %s%s\n", cRed, sig.Kind, sig.Name, result.Err.Error(), reset)
		} else {
			fmt.Fprintf(o.w, "%sfailed validation: %s %s%s\n", cRed, sig.Name, result.Err.Error(), reset)
		}
		o.nErrors++
	case validator.Skipped:
		if o.verbose {
			fmt.Fprintf(o.w, "%s-%s %s: ", cYellow, reset, result.Resource.Path)
			if sig.Kind != "" && sig.Name != "" {
				fmt.Fprintf(o.w, "%s%s %s skipped%s\n", cYellow, sig.Kind, sig.Name, reset)
			} else if sig.Kind != "" {
				fmt.Fprintf(o.w, "%s%s skipped%s\n", cYellow, sig.Kind, reset)
			} else {
				fmt.Fprintf(o.w, "%sskipped%s\n", cYellow, reset)
			}
		}
		o.nSkipped++
	case validator.Empty: // sent to ensure we count the filename as parsed
	}

	return err
}

func (o *prettyo) Flush() error {
	var err error
	if o.withSummary {
		nFiles := len(o.files)
		nResources := o.nValid + o.nInvalid + o.nErrors + o.nSkipped
		resourcesPlural := ""
		if nResources > 1 {
			resourcesPlural = "s"
		}
		filesPlural := ""
		if nFiles > 1 {
			filesPlural = "s"
		}
		if o.isStdin {
			_, err = fmt.Fprintf(o.w, "Summary: %d resource%s found parsing stdin - Valid: %d, Invalid: %d, Errors: %d, Skipped: %d\n", nResources, resourcesPlural, o.nValid, o.nInvalid, o.nErrors, o.nSkipped)
		} else {
			_, err = fmt.Fprintf(o.w, "Summary: %d resource%s found in %d file%s - Valid: %d, Invalid: %d, Errors: %d, Skipped: %d\n", nResources, resourcesPlural, nFiles, filesPlural, o.nValid, o.nInvalid, o.nErrors, o.nSkipped)
		}
	}

	return err
}

package resource

import (
	"os"
	"strings"
	"sync"
	"testing"
	"time"
)

type MockFileInfo struct {
	fileName string
}

func NewMockFileInfo(filename string) *MockFileInfo {
	return &MockFileInfo{fileName: filename}
}
func (m *MockFileInfo) Name() string       { return m.fileName }
func (m *MockFileInfo) Size() int64        { return 0 }           // length in bytes for regular files; system-dependent for others
func (m *MockFileInfo) Mode() os.FileMode  { return 0 }           // file mode bits
func (m *MockFileInfo) ModTime() time.Time { return time.Time{} } // modification time
func (m *MockFileInfo) IsDir() bool        { return false }       // abbreviation for Mode().IsDir()
func (m *MockFileInfo) Sys() interface{}   { return nil }         // underlying data source (can return nil)

func TestIsYamlFile(t *testing.T) {
	for i, testCase := range []struct {
		filename string
		expect   bool
	}{
		{
			"file.yaml",
			true,
		},
		{
			"/path/to/my/file.yaml",
			true,
		},
		{
			"file.yml",
			true,
		},
		{
			"/path/to/my/file.yml",
			true,
		},
		{
			"file.notyaml",
			false,
		},
		{
			"/path/to/my/file.notyaml",
			false,
		},
		{
			"/path/to/my/file",
			false,
		},
	} {
		if got := isYAMLFile(NewMockFileInfo(testCase.filename)); got != testCase.expect {
			t.Errorf("test %d: for filename %s, expected %t, got %t", i+1, testCase.filename, testCase.expect, got)
		}
	}
}

func TestIsJSONFile(t *testing.T) {
	for i, testCase := range []struct {
		filename string
		expect   bool
	}{
		{
			"file.json",
			true,
		},
		{
			"/path/to/my/file.json",
			true,
		},
		{
			"file.notjson",
			false,
		},
		{
			"/path/to/my/file",
			false,
		},
	} {
		if got := isJSONFile(NewMockFileInfo(testCase.filename)); got != testCase.expect {
			t.Errorf("test %d: for filename %s, expected %t, got %t", i+1, testCase.filename, testCase.expect, got)
		}
	}
}

func TestFindResourcesInReader(t *testing.T) {
	maxResourceSize := 4 * 1024 * 1024   // 4MB ought to be enough for everybody
	buf := make([]byte, maxResourceSize) // We reuse this to avoid multiple large memory allocations

	for i, testCase := range []struct {
		filePath string
		yamlData string
		res      []Resource
		errs     []error
	}{
		{
			"manifest.yaml",
			``,
			[]Resource{
				{
					Path:  "manifest.yaml",
					Bytes: nil,
					sig:   nil,
				},
			},
			nil,
		},
		{
			"manifest.yaml",
			`---
foo: bar
`,
			[]Resource{
				{
					Path:  "manifest.yaml",
					Bytes: []byte("---\nfoo: bar\n"),
					sig:   nil,
				},
			},
			nil,
		},
		{
			"manifest.yaml",
			`---
foo: bar
---
lorem: ipsum
`,
			[]Resource{
				{
					Path:  "manifest.yaml",
					Bytes: []byte("---\nfoo: bar"),
					sig:   nil,
				},
				{
					Path:  "manifest.yaml",
					Bytes: []byte("lorem: ipsum\n"),
					sig:   nil,
				},
			},
			nil,
		},
	} {
		res := make(chan Resource)
		errs := make(chan error)
		receivedResources := []Resource{}
		receivedErrs := []error{}
		var wg sync.WaitGroup
		wg.Add(1)

		go func() {
			for {
				select {
				case receivedResource, ok := <-res:
					if ok {
						receivedResources = append(receivedResources, receivedResource)
						continue
					}
					res = nil

				case receivedErr, ok := <-errs:
					if ok {
						receivedErrs = append(receivedErrs, receivedErr)
						continue
					}
					errs = nil
				}

				if res == nil && errs == nil {
					break
				}
			}
			wg.Done()
		}()

		r := strings.NewReader(testCase.yamlData)
		findResourcesInReader(testCase.filePath, r, res, errs, buf)
		close(res)
		close(errs)
		wg.Wait()

		if len(receivedResources) != len(testCase.res) {
			t.Errorf("test %d: expected %d resources, received %d: %+v", i, len(testCase.res), len(receivedResources), receivedResources)
			continue
		}

		for j, r := range receivedResources {
			if r.Path != testCase.res[j].Path {
				t.Errorf("test %d, resource %d, expected path %s, received %s", i, j, testCase.res[j].Path, r.Path)
			}

			if string(r.Bytes) != string(testCase.res[j].Bytes) {
				t.Errorf("test %d, resource %d, expected Bytes %s, received %s", i, j, string(testCase.res[j].Bytes), string(r.Bytes))
			}
		}
	}
}
package resource_test

import (
